import { CARD_BY_ID, HERO_BY_ID, canonicalHero, ROLES } from '../../shared/catalog';
import type { GameCard, PublicPlayer, RoomSnapshot } from '../../shared/protocol';
export const esc=(value:unknown)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export const icon=(name:string)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="${({play:'M8 5l11 7-11 7Z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3Z M12 6v15',arrow:'M4 12h16 M14 6l6 6-6 6',close:'M6 6l12 12 M6 18L18 6',back:'M15 5l-7 7 7 7',users:'M15 20v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2 M8 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M23 20v-2a4 4 0 0 0-3-3.9',copy:'M9 9h12v12H9Z M15 9V3H3v12h6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',settings:'M5 5h14v14H5Z M8 9h8 M8 15h8 M10 7v4 M14 13v4',chat:'M3 4h18v13H8l-5 4Z M7 8h10 M7 12h7',sound:'M3 9h4l5-4v14l-5-4H3Z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',muted:'M3 9h4l5-4v14l-5-4H3Z M16 9l6 6 M16 15l6-6',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z'} as Record<string,string>)[name]||'M4 12h16'}"/></svg>`;
export const btn=(action:string,label:string,kind='',extra='')=>`<button type="button" class="button ${kind}" data-action="${action}" ${extra}>${label}</button>`;
export function art(index:number,hero=false):string {
  // The generated weapon row has eight cells; skip its duplicate trigrams tile.
  const row=hero?Math.floor(index/5):Math.floor(index/7),cols=hero?5:row===4?8:7,rows=hero?3:6;
  const column=hero?index%5:row===4?(index===34?7:index-28):index%7;
  return `style="background-size:${cols*100}% ${rows*100}%;--art-x:${column/(cols-1)*100}%;--art-y:${row/(rows-1)*100}%"`;
}
export function portrait(id:string,classes=''):string {const hero=HERO_BY_ID[canonicalHero(id)],index=hero?.art||0;if(index>=13){const tile=index-13;return `<div class="portrait ${classes}" style="background-image:url('/art/heroes-experimental-atlas.png');background-size:300% 200%;--art-x:${tile%3/2*100}%;--art-y:${Math.floor(tile/3)*100}%" aria-hidden="true"></div>`;}return `<div class="portrait ${classes}" ${art(index,true)} aria-hidden="true"></div>`;}
export const rank=(r:number)=>({1:'A',11:'J',12:'Q',13:'K'} as Record<number,string>)[r]||String(r);
export const suit=(s:string)=>({SPADE:'♠',HEART:'♥',CLUB:'♣',DIAMOND:'♦'} as Record<string,string>)[s]||'?';
export function cardMarkup(card:GameCard,action='card',selected=false):string {const def=CARD_BY_ID[card.name];return `<button type="button" class="hand-card ${selected?'selected':''} ${['HEART','DIAMOND'].includes(card.suit)?'red-suit':''}" data-action="${action}" data-card="${esc(card.id)}" aria-pressed="${selected}" aria-label="${esc(def?.name||card.name)} ${suit(card.suit)} ${rank(card.rank)}"><div class="card-art" ${art(def?.art||0)} aria-hidden="true"></div><span class="card-rank">${rank(card.rank)}<small>${suit(card.suit)}</small></span><span class="card-title">${esc(def?.name||card.name)}</span><span class="card-kind">${({BASIC:'พื้นฐาน',KIT:'กลยุทธ์',DELAYED:'พิจารณา',EQUIPMENT:'อุปกรณ์'} as Record<string,string>)[card.type]||''}${def?.range?' · ระยะ '+def.range:''}</span></button>`;}
export function publicCardMarkup(name:string,card:GameCard|undefined,extra=''):string {
  const def=CARD_BY_ID[name]||CARD_BY_ID[card?.name||''];
  const hasRank=!!card&&['SPADE','HEART','CLUB','DIAMOND'].includes(card.suit)&&card.rank>=1&&card.rank<=13;
  return `<button type="button" class="hand-card public-card ${hasRank&&['HEART','DIAMOND'].includes(card!.suit)?'red-suit':''}" data-action="public-play" ${extra} aria-label="ดู${esc(def?.name||name)}${hasRank?' '+suit(card!.suit)+' '+rank(card!.rank):''}"><div class="card-art" ${art(def?.art||0)} aria-hidden="true"></div>${hasRank?`<span class="card-rank">${rank(card!.rank)}<small>${suit(card!.suit)}</small></span>`:''}<span class="card-title">${esc(def?.name||name)}</span><span class="card-kind">${card&&card.name!==name?'แปลงจาก '+esc(CARD_BY_ID[card.name]?.name||card.name):'การ์ดที่เล่นแล้ว'}</span></button>`;
}
export function opponentBacks(count:number):string {
  const visible=Math.min(6,Math.max(0,count));
  return `<span class="opponent-hand" aria-hidden="true">${Array.from({length:visible},(_,index)=>`<span class="opponent-card-back" style="--back-offset:${index-(visible-1)/2};--back-layer:${index}"></span>`).join('')}</span>`;
}
export function distance(state:RoomSnapshot,from:string,to:string):number {const order=state.turnOrder.filter(id=>state.players[id]?.isAlive);const a=order.indexOf(from),b=order.indexOf(to);if(a<0||b<0)return 999;const d=Math.abs(a-b);return Math.max(1,Math.min(d,order.length-d)-(state.players[from].equipment.offensiveHorse?1:0)+(state.players[to].equipment.defensiveHorse?1:0));}
export function canUseAs(player:PublicPlayer,card:GameCard,required:string):boolean {const h=canonicalHero(player.character),red=['HEART','DIAMOND'].includes(card.suit);return card.name===required||required==='SLASH'&&card.name==='THUNDER_ATTACK'||h==='ZHAO_YUN'&&(['SLASH','DODGE'].includes(card.name)&&['SLASH','DODGE'].includes(required))||required==='SLASH'&&h==='GUAN_YU'&&red||required==='DODGE'&&h==='ZHEN_JI'&&!red;}
export function responder(state:RoomSnapshot):string|null {const p=state.pendingAction;if(!p)return null;return p.type==='DYING'?state.turnOrder[p.currentAskerIdx]:p.type==='WAITING_FOR_AOE'?p.targets?.[p.currentTargetIndex]:p.type==='WAITING_FOR_SLASH_DUEL'?p.currentPlayerToSlash:p.type==='WAITING_FOR_BUMPER_PICK'?p.currentPickerId:['WAITING_FOR_FIRE_MATCH','WAITING_FOR_GREEN_DRAGON','WAITING_FOR_AXE_DISCARD','WAITING_FOR_TRIDENT_DISCARD','WAITING_FOR_FROST_DISCARD'].includes(p.type)?p.sourcePlayerId:p.targetPlayerId;}
export const roleMarkup=(role:string)=>`<span class="role-seal" style="--role:${ROLES[role]?.color||ROLES.UNKNOWN.color}">${esc(ROLES[role]?.seal||'?')}</span>`;
